WITH base AS (SELECT ss.ss_store_sk AS store_id, hd.hd_buy_potential AS buy_potential, ib.ib_lower_bound, ib.ib_upper_bound, SUM(ss.ss_net_profit) AS total_sales_profit, SUM(sr.sr_net_loss) AS total_return_loss, SUM(ss.ss_net_profit) - SUM(sr.sr_net_loss) AS net_contribution FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk JOIN store_returns sr ON ss.ss_ticket_number = sr.sr_ticket_number AND ss.ss_item_sk = sr.sr_item_sk GROUP BY ss.ss_store_sk, hd.hd_buy_potential, ib.ib_lower_bound, ib.ib_upper_bound) SELECT store_id, buy_potential, ib_lower_bound, ib_upper_bound, total_sales_profit, total_return_loss, net_contribution, CASE WHEN net_contribution > 0 THEN 'Positive' ELSE 'Negative' END AS contribution_sign, DENSE_RANK() OVER (ORDER BY net_contribution DESC) AS net_contribution_rank, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY net_contribution DESC) AS store_rank_by_contribution FROM base ORDER BY net_contribution_rank LIMIT 20
